Here is a complete, self-contained React component implementing a searchable, paginated, and sortable data table using only React hooks and standard HTML/CSS.

```tsx
import React, { useState, useMemo, useCallback } from 'react';

// --- Types ---
type SortDirection = 'asc' | 'desc' | null;

interface SortConfig {
  key: string | null;
  direction: SortDirection;
}

interface DataItem {
  id: number;
  name: string;
  role: string;
  email: string;
  status: 'Active' | 'Inactive' | 'Pending';
  joinDate: string;
  salary: number;
}

// --- Mock Data ---
const MOCK_DATA: DataItem[] = Array.from({ length: 50 }, (_, i) => ({
  id: i + 1,
  name: `User ${i + 1}`,
  role: i % 3 === 0 ? 'Admin' : i % 3 === 1 ? 'Editor' : 'Viewer',
  email: `user${i + 1}@example.com`,
  status: i % 4 === 0 ? 'Inactive' : i % 4 === 1 ? 'Pending' : 'Active',
  joinDate: new Date(Date.now() - Math.floor(Math.random() * 10000000000)).toISOString().split('T')[0],
  salary: Math.floor(Math.random() * 50000) + 30000,
}));

// --- Styles (CSS-in-JS for zero-dependency) ---
const styles = {
  container: {
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
    maxWidth: '1000px',
    margin: '2rem auto',
    padding: '1rem',
    backgroundColor: '#fff',
    borderRadius: '8px',
    boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '1rem',
  },
  searchInput: {
    padding: '0.5rem 1rem',
    borderRadius: '4px',
    border: '1px solid #ddd',
    width: '250px',
    fontSize: '0.9rem',
  },
  tableWrapper: {
    overflowX: 'auto' as const,
    border: '1px solid #eee',
    borderRadius: '4px',
  },
  table: {
    width: '100%',
    borderCollapse: 'collapse' as const,
    fontSize: '0.9rem',
  },
  th: {
    padding: '12px 16px',
    textAlign: 'left' as const,
    backgroundColor: '#f8f9fa',
    borderBottom: '2px solid #dee2e6',
    cursor: 'pointer',
    userSelect: 'none' as const,
    fontWeight: 600,
    color: '#333',
  },
  td: {
    padding: '12px 16px',
    borderBottom: '1px solid #dee2e6',
    color: '#555',
  },
  pagination: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginTop: '1rem',
    padding: '0 1rem',
  },
  button: {
    padding: '0.5rem 1rem',
    border: '1px solid #ddd',
    backgroundColor: '#fff',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '0.85rem',
    transition: 'background 0.2s',
  },
  buttonDisabled: {
    opacity: 0.5,
    cursor: 'not-allowed',
  },
  badge: (status: string) => ({
    padding: '4px 8px',
    borderRadius: '12px',
    fontSize: '0.75rem',
    fontWeight: 600,
    backgroundColor: status === 'Active' ? '#d4edda' : status === 'Inactive' ? '#f8d7da' : '#fff3cd',
    color: status === 'Active' ? '#155724' : status === 'Inactive' ? '#721c24' : '#856404',
  }),
  sortIcon: (direction: SortDirection) => ({
    marginLeft: '8px',
    fontSize: '0.8rem',
    color: direction ? '#007bff' : '#ccc',
  }),
};

// --- Sub-Components ---

const SortIcon = ({ direction }: { direction: SortDirection }) => {
  if (!direction) return <span style={styles.sortIcon(null)}>↕</span>;
  return direction === 'asc' ? <span style={styles.sortIcon('asc')}>↑</span> : <span style={styles.sortIcon('desc')}>↓</span>;
};

// --- Main Component ---

interface DataTableProps {
  data: DataItem[];
  columns: { key: keyof DataItem; label: string }[];
}

export const DataTable: React.FC<DataTableProps> = ({ data, columns }) => {
  // --- State ---
  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: null, direction: null });
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  // --- Handlers ---

  const handleSort = useCallback((key: keyof DataItem) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
    setCurrentPage(1); // Reset to first page on sort
  }, [sortConfig]);

  const handleSearch = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1); // Reset to first page on search
  }, []);

  // --- Derived Data (Memoized) ---

  // 1. Filter Data
  const filteredData = useMemo(() => {
    if (!searchTerm) return data;
    const lowerTerm = searchTerm.toLowerCase();
    return data.filter((row) =>
      Object.values(row).some((val) =>
        String(val).toLowerCase().includes(lowerTerm)
      )
    );
  }, [data, searchTerm]);

  // 2. Sort Data
  const sortedData = useMemo(() => {
    if (!sortConfig.key || !sortConfig.direction) return filteredData;

    const sorted = [...filteredData].sort((a, b) => {
      const aValue = a[sortConfig.key];
      const bValue = b[sortConfig.key];

      if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });

    return sorted;
  }, [filteredData, sortConfig]);

  // 3. Paginate Data
  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * rowsPerPage;
    return sortedData.slice(startIndex, startIndex + rowsPerPage);
  }, [sortedData, currentPage, rowsPerPage]);

  const totalPages = Math.ceil(sortedData.length / rowsPerPage);

  // --- Render Helpers ---

  const renderCell = (row: DataItem, key: keyof DataItem) => {
    const value = row[key];

    // Special formatting for specific columns
    if (key === 'status') {
      return <span style={styles.badge(value as string)}>{value}</span>;
    }
    if (key === 'salary') {
      return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value as number);
    }

    return value;
  };

  return (
    <div style={styles.container}>
      {/* Header Section */}
      <div style={styles.header}>
        <h2 style={{ margin: 0, fontSize: '1.5rem', color: '#333' }}>Employee Directory</h2>
        <input
          type="text"
          placeholder="Search..."
          value={searchTerm}
          onChange={handleSearch}
          style={styles.searchInput}
        />
      </div>

      {/* Table Section */}
      <div style={styles.tableWrapper}>
        <table style={styles.table}>
          <thead>
            <tr>
              {columns.map((col) => (
                <th
                  key={col.key}
                  onClick={() => handleSort(col.key)}
                  style={styles.th}
                >
                  {col.label}
                  <SortIcon direction={sortConfig.key === col.key ? sortConfig.direction : null} />
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {paginatedData.length > 0 ? (
              paginatedData.map((row) => (
                <tr key={row.id}>
                  {columns.map((col) => (
                    <td key={`${row.id}-${col.key}`} style={styles.td}>
                      {renderCell(row, col.key)}
                    </td>
                  ))}
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={columns.length} style={{ ...styles.td, textAlign: 'center', padding: '2rem' }}>
                  No results found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Section */}
      <div style={styles.pagination}>
        <div style={{ fontSize: '0.9rem', color: '#666' }}>
          Showing {paginatedData.length > 0 ? (currentPage - 1) * rowsPerPage + 1 : 0} to{' '}
          {Math.min(currentPage * rowsPerPage, sortedData.length)} of {sortedData.length} entries
        </div>

        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <button
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            style={{
              ...styles.button,
              ...(currentPage === 1 ? styles.buttonDisabled : {})
            }}
          >
            Previous
          </button>

          {/* Page Numbers (Simplified) */}
          {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
            <button
              key={page}
              onClick={() => setCurrentPage(page)}
              style={{
                ...styles.button,
                backgroundColor: currentPage === page ? '#007bff' : '#fff',
                color: currentPage === page ? '#fff' : '#333',
                border: currentPage === page ? '1px solid #007bff' : '1px solid #ddd',
              }}
            >
              {page}
            </button>
          ))}

          <button
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            style={{
              ...styles.button,
              ...(currentPage === totalPages ? styles.buttonDisabled : {})
            }}
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
};

// --- Usage Example ---

const App = () => {
  const columns = [
    { key: 'name', label: 'Name' },
    { key: 'role', label: 'Role' },
    { key: 'email', label: 'Email' },
    { key: 'status', label: 'Status' },
    { key: 'joinDate', label: 'Joined' },
    { key: 'salary', label: 'Salary' },
  ];

  return (
    <div>
      <DataTable data={MOCK_DATA} columns={columns} />
    </div>
  );
};

export default App;
```

prompt:
This function sometimes returns NaN when input comes from a form. Find the bug and fix it defensively:

```javascript
function calculateInvoiceTotal(subtotal, taxRate, discountAmount, shippingFee) {
  // taxRate comes as percentage e.g. "8.25" or 8.25
  const tax = subtotal * (taxRate / 100);
  const total = subtotal + tax - discountAmount + shippingFee;
  return Number(total.toFixed(2));
}
```

content:
# Bug Analysis and Fix

## Root Cause
Form inputs return **strings**, and empty fields return **empty strings (`""`)**. When used in arithmetic operations:
- `"" * 100` → `0` (works)
- `"" + 100` → `"100"` (string concatenation)
- `Number("")` → `0` (works)
- `Number("abc")` → `NaN` (fails)

The original code doesn't validate or convert inputs, so non-numeric or empty values cause `NaN`.

## Defensive Fix

```javascript
function calculateInvoiceTotal(subtotal, taxRate, discountAmount, shippingFee) {
  // Helper to safely convert input to number with validation
  const toNumber = (value, fieldName) => {
    const num = Number(value);
    if (isNaN(num)) {
      throw new Error(`Invalid ${fieldName}: "${value}" is not a valid number`);
    }
    return num;
  };

  // Convert and validate all inputs
  const subtotalNum = toNumber(subtotal, 'subtotal');
  const taxRateNum = toNumber(taxRate, 'tax rate');
  const discountAmountNum = toNumber(discountAmount, 'discount amount');
  const shippingFeeNum = toNumber(shippingFee, 'shipping fee');

  // Optional: validate business logic constraints
  if (subtotalNum < 0) {
    throw new Error('Subtotal cannot be negative');
  }
  if (taxRateNum < 0 || taxRateNum > 100) {
    throw new Error('Tax rate must be between 0 and 100');
  }
  if (discountAmountNum < 0) {
    throw new Error('Discount amount cannot be negative');
  }
  if (shippingFeeNum < 0) {
    throw new Error('Shipping fee cannot be negative');
  }

  // Calculate tax
  const tax = subtotalNum * (taxRateNum / 100);

  // Calculate total
  const total = subtotalNum + tax - discountAmountNum + shippingFeeNum;

  // Round to 2 decimal places and return as number
  return Number(total.toFixed(2));
}
```

## Alternative: Lenient Version (No Exceptions)

If you prefer to handle invalid inputs gracefully without throwing:

```javascript
function calculateInvoiceTotal(subtotal, taxRate, discountAmount, shippingFee) {
  const toNumber = (value) => {
    const num = Number(value);
    return isNaN(num) ? 0 : num;
  };

  const subtotalNum = toNumber(subtotal);
  const taxRateNum = toNumber(taxRate);
  const discountAmountNum = toNumber(discountAmount);
  const shippingFeeNum = toNumber(shippingFee);

  const tax = subtotalNum * (taxRateNum / 100);
  const total = subtotalNum + tax - discountAmountNum + shippingFeeNum;

  return Number(total.toFixed(2));
}
```

## Usage Examples

```javascript
// ✅ Valid inputs
calculateInvoiceTotal(100, 8.25, 10, 5);     // 102.27
calculateInvoiceTotal("100", "8.25", "10", "5"); // 102.27

// ✅ Empty strings handled
calculateInvoiceTotal("100", "", "", "");    // 100

// ❌ Invalid input (throws in strict version)
calculateInvoiceTotal("abc", 8.25, 10, 5);   // Error: Invalid subtotal

// ✅ Edge cases
calculateInvoiceTotal(0, 0, 0, 0);           // 0
calculateInvoiceTotal(100, 100, 0, 0);       // 200
```

## Key Improvements

| Issue | Original | Fixed |
|-------|----------|-------|
| Input type | Assumed numbers | Converts strings safely |
| Empty values | May cause NaN | Defaults to 0 or throws |
| Non-numeric values | Causes NaN | Validates and throws |
| Negative values | Allowed | Validated (optional) |
| Tax rate range | Not checked | 0–100% enforced |
| Error messages | None | Descriptive errors |

Choose the strict version for robust validation or the lenient version for graceful degradation, depending on your application's needs.

